using System;
using System.Collections.Generic;
using System.Diagnostics;
using System.IO;
using System.Linq;
using System.Text;
using Microsoft.Win32;

namespace BridgeQuickTool {
    // Span-based KeyValues editing: only App 550's quoted value is replaced.
    public sealed class VdfNode {
        public string Key,Value;
        public int ValueStart,ValueEnd,Close;
        public List<VdfNode> Children;
        public VdfNode Child(string name){var matches=(Children??new List<VdfNode>()).Where(n=>n.Key.Equals(name,StringComparison.OrdinalIgnoreCase)).ToArray();if(matches.Length>1)throw new InvalidDataException("Duplicate KeyValues key: "+name);return matches.SingleOrDefault();}
        public VdfNode At(params string[] names){var n=this;foreach(string name in names){if(n==null)return null;n=n.Child(name);}return n;}
    }
    public sealed class VdfDocument {
        readonly string text;int pos,tokens;
        public readonly VdfNode Root;
        public VdfDocument(string source){if(source.Length>8*1024*1024)throw new InvalidDataException("KeyValues file is too large.");text=source;Root=new VdfNode{Children=Read(false,0)};}
        void Space(){while(pos<text.Length){if(Char.IsWhiteSpace(text[pos])){pos++;continue;}if(text[pos]=='/'&&pos+1<text.Length&&text[pos+1]=='/'){while(pos<text.Length&&text[pos]!='\n')pos++;continue;}break;}}
        string Token(out int start,out int end){Space();if(++tokens>300000||pos>=text.Length)throw new InvalidDataException("Invalid KeyValues token.");start=pos;var s=new StringBuilder();if(text[pos]=='"'){pos++;bool closed=false;while(pos<text.Length){char c=text[pos++];if(c=='"'){closed=true;break;}if(c=='\\'&&pos<text.Length){char next=text[pos++];if(next=='\\'||next=='"')c=next;else if(next=='n')c='\n';else if(next=='t')c='\t';else{s.Append('\\');c=next;}}s.Append(c);}if(!closed)throw new InvalidDataException("Unclosed KeyValues string.");}else{while(pos<text.Length&&!Char.IsWhiteSpace(text[pos])&&text[pos]!='{'&&text[pos]!='}')s.Append(text[pos++]);if(s.Length==0)throw new InvalidDataException("Expected KeyValues string.");}end=pos;return s.ToString();}
        List<VdfNode> Read(bool nested,int depth){if(depth>32)throw new InvalidDataException("KeyValues nesting exceeds limit.");var nodes=new List<VdfNode>();while(true){Space();if(pos>=text.Length){if(nested)throw new InvalidDataException("Unclosed KeyValues object.");return nodes;}if(text[pos]=='}'){if(!nested)throw new InvalidDataException("Unexpected KeyValues brace.");return nodes;}int a,b;string key=Token(out a,out b);Space();var node=new VdfNode{Key=key};if(pos<text.Length&&text[pos]=='{'){pos++;node.Children=Read(true,depth+1);node.Close=pos;pos++;}else node.Value=Token(out node.ValueStart,out node.ValueEnd);nodes.Add(node);}}
        public static string Quote(string value){return "\""+value.Replace("\\","\\\\").Replace("\"","\\\"").Replace("\n","\\n").Replace("\t","\\t")+"\"";}
        VdfNode Apps(){var apps=Root.At("UserLocalConfigStore","Software","Valve","Steam","apps");if(apps==null||apps.Children==null)throw new InvalidDataException("Steam apps section was not found in this account's localconfig.vdf.");return apps;}
        public string LaunchOptions(){var app=Apps().Child("550");if(app!=null&&app.Children==null)throw new InvalidDataException("Invalid App 550 object.");var value=app==null?null:app.Child("LaunchOptions");if(value!=null&&value.Children!=null)throw new InvalidDataException("Invalid LaunchOptions value.");return value==null?"":value.Value;}
        public string WithLaunchOptions(string value){ValidateOptions(value);LaunchOptions();var apps=Apps();var app=apps.Child("550");var node=app==null?null:app.Child("LaunchOptions");if(node!=null)return text.Substring(0,node.ValueStart)+Quote(value)+text.Substring(node.ValueEnd);string nl=text.Contains("\r\n")?"\r\n":"\n";string entry="\t\t\t\t\t\t\"LaunchOptions\"\t\t"+Quote(value)+nl;if(app!=null)return text.Insert(app.Close,nl+entry);return text.Insert(apps.Close,nl+"\t\t\t\t\t\"550\""+nl+"\t\t\t\t\t{"+nl+entry+"\t\t\t\t\t}"+nl);}
        public static void ValidateOptions(string value){if(value==null||value.Length>4096||value.Any(c=>Char.IsControl(c)))throw new InvalidOperationException("Launch options must be one line, at most 4096 characters.");}
    }
    public sealed class SteamOptions {
        public string SteamRoot,AccountId,Path,Hash,Value;
        internal ConfigDocument Document;
    }
    public static class SteamSupport {
        public static bool SteamRunning(){var ps=Process.GetProcessesByName("steam");try{return ps.Length>0;}finally{foreach(var p in ps)p.Dispose();}}
        public static string FindSteam(){using(var key=Registry.CurrentUser.OpenSubKey(@"Software\Valve\Steam")){string p=key==null?null:key.GetValue("SteamPath") as string;if(!String.IsNullOrEmpty(p)&&Directory.Exists(p))return Path.GetFullPath(p);}string fallback=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.ProgramFilesX86),"Steam");return Directory.Exists(fallback)?fallback:null;}
        public static string[] Games(string steam){if(String.IsNullOrEmpty(steam))return new string[0];var libraries=new HashSet<string>(StringComparer.OrdinalIgnoreCase){Path.GetFullPath(steam)};string catalog=Path.Combine(steam,"steamapps","libraryfolders.vdf");if(File.Exists(catalog)){var entries=new VdfDocument(ConfigDocument.Load(catalog).Text).Root.Child("libraryfolders");if(entries!=null&&entries.Children!=null)foreach(var item in entries.Children){string p=item.Children==null?item.Value:(item.Child("path")==null?null:item.Child("path").Value);if(!String.IsNullOrEmpty(p)&&Path.IsPathRooted(p)&&!p.StartsWith(@"\\"))libraries.Add(Path.GetFullPath(p));}}var games=new List<string>();foreach(string library in libraries){if(library.StartsWith(@"\\"))continue;string manifest=Path.Combine(library,"steamapps","appmanifest_550.acf");if(!File.Exists(manifest))continue;Core.Guard(manifest,library);var state=new VdfDocument(ConfigDocument.Load(manifest).Text).Root.Child("AppState");if(state==null||state.Child("appid")==null||state.Child("appid").Value!="550")continue;var folder=state.Child("installdir");if(folder==null||String.IsNullOrEmpty(folder.Value))continue;string common=Path.Combine(library,"steamapps","common");string game=Path.GetFullPath(Path.Combine(common,folder.Value));Core.Guard(game,common);if(File.Exists(Path.Combine(game,"left4dead2.exe"))&&Directory.Exists(Path.Combine(game,"bin")))games.Add(game);}return games.Distinct(StringComparer.OrdinalIgnoreCase).ToArray();}
        static string ActiveAccount(string steam){using(var key=Registry.CurrentUser.OpenSubKey(@"Software\Valve\Steam\ActiveProcess")){object id=key==null?null:key.GetValue("ActiveUser");if(id is int&&(int)id!=0)return unchecked((uint)(int)id).ToString();}string login=Path.Combine(steam,"config","loginusers.vdf");if(File.Exists(login)){var users=new VdfDocument(ConfigDocument.Load(login).Text).Root.Child("users");if(users!=null&&users.Children!=null){var recent=users.Children.Where(n=>n.Child("MostRecent")!=null&&n.Child("MostRecent").Value=="1").ToArray();ulong id;if(recent.Length==1&&UInt64.TryParse(recent[0].Key,out id)&&id>=76561197960265728UL&&id-76561197960265728UL<=UInt32.MaxValue)return (id-76561197960265728UL).ToString();}}throw new InvalidOperationException("Cannot identify the active Steam account. Sign into Steam, then refresh; no account was guessed.");}
        public static SteamOptions Read(string steam,string account){if(String.IsNullOrEmpty(steam))throw new InvalidOperationException("Steam installation was not found.");if(String.IsNullOrEmpty(account)||account.Any(c=>c<'0'||c>'9'))throw new InvalidDataException("Invalid Steam account ID.");string path=Path.Combine(steam,"userdata",account,"config","localconfig.vdf");Core.Guard(path,steam);var doc=ConfigDocument.Load(path);return new SteamOptions{SteamRoot=steam,AccountId=account,Path=path,Hash=doc.Hash,Document=doc,Value=new VdfDocument(doc.Text).LaunchOptions()};}
        public static SteamOptions Current(){string steam=FindSteam();if(steam==null)throw new InvalidOperationException("Steam installation was not found.");return Read(steam,ActiveAccount(steam));}
        static byte[] Encode(ConfigDocument doc,string text){byte[] content=doc.TextEncoding.GetBytes(text);if(!doc.Bom)return content;byte[] prefix=doc.TextEncoding.CodePage==1200?new byte[]{255,254}:doc.TextEncoding.CodePage==1201?new byte[]{254,255}:new byte[]{239,187,191};return prefix.Concat(content).ToArray();}
        public static string Save(Core core,SteamOptions expected,string value,Func<bool> steamRunning){
            VdfDocument.ValidateOptions(value);if(expected==null)throw new InvalidOperationException("Read Steam launch options first.");if(steamRunning())throw new InvalidOperationException("Exit Steam before saving launch options so it cannot overwrite the edit. Refresh after switching accounts.");
            Core.Guard(expected.Path,expected.SteamRoot);var fresh=Read(expected.SteamRoot,expected.AccountId);if(fresh.Hash!=expected.Hash)throw new InvalidOperationException("Steam configuration changed since reading. Refresh before saving.");if(fresh.Value==value)return null;
            string content=new VdfDocument(fresh.Document.Text).WithLaunchOptions(value);var verify=new VdfDocument(content);if(verify.LaunchOptions()!=value)throw new InvalidDataException("Launch-options roundtrip failed.");
            string dir=Path.Combine(core.StateRoot,"steam-launch-backups");Core.Guard(dir,core.GameRoot);Directory.CreateDirectory(dir);string id=DateTime.UtcNow.ToString("yyyyMMdd-HHmmss")+"-"+Guid.NewGuid().ToString("N");string backup=Path.Combine(dir,"localconfig-"+expected.AccountId+"-"+id+".vdf");string stage=expected.Path+".quick-tool-"+Guid.NewGuid().ToString("N")+".tmp";
            try{File.Copy(expected.Path,backup,false);if(Core.HashFile(backup)!=expected.Hash)throw new IOException("Configuration changed while backing up; save was cancelled.");byte[] bytes=Encode(fresh.Document,content);using(var stream=new FileStream(stage,FileMode.CreateNew,FileAccess.Write,FileShare.None)){stream.Write(bytes,0,bytes.Length);stream.Flush(true);}if(steamRunning()||Core.HashFile(expected.Path)!=expected.Hash)throw new InvalidOperationException("Steam started or configuration changed; save was cancelled.");File.Replace(stage,expected.Path,null);if(Core.HashFile(expected.Path)!=Core.HashBytes(bytes))throw new IOException("Saved configuration changed unexpectedly; preserve the backup for review.");return backup;}finally{if(File.Exists(stage))File.Delete(stage);}
        }
        public static string[] Args(string text){var args=new List<string>();var word=new StringBuilder();bool quote=false,started=false;for(int i=0;i<text.Length;i++){char c=text[i];if(c=='\\'){int count=1;while(i+1<text.Length&&text[i+1]=='\\'){count++;i++;}if(i+1<text.Length&&text[i+1]=='"'){word.Append('\\',count/2);i++;if((count&1)!=0)word.Append('"');else quote=!quote;}else word.Append('\\',count);started=true;continue;}if(c=='"'){quote=!quote;started=true;continue;}if(Char.IsWhiteSpace(c)&&!quote){if(started){args.Add(word.ToString());word.Length=0;started=false;}}else{word.Append(c);started=true;}}if(quote)throw new InvalidDataException("Unbalanced quote in launch options.");if(started)args.Add(word.ToString());return args.ToArray();}
    }
}
